import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1050;
const CX = W / 2;

const COLORS = {
  latent: { fill: '#ede7f6', stroke: '#4527a0' },
  time: { fill: '#fff3e0', stroke: '#e65100' },
  model: { fill: '#e3f2fd', stroke: '#1976d2' },
  schedule: { fill: '#e0f2f1', stroke: '#00897b' },
  update: { fill: '#fce4ec', stroke: '#c62828' },
  noise: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 72;
const VEC_H = 34;
const SEQ_W = 150;
const STEP_GAP = 160;
const BOX_TO_ROW = 130;
const ROW_GAP = 120;
const SHAPE_GAP = 56;

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

interface SchedulerStep extends StepInfo {}
type SchedulerType = 'ddpm' | 'ddim' | 'euler' | 'dpm++';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 940
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 32, 220);
  const h = 30;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 9, color, font: 'monospace' });
}

function seqMatrix(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = SEQ_W, h = MAT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 5, dimTop: 'P', dimRight: 'D',
  });
}

function smallVec(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = 100, h = VEC_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 1,
  });
}

function smallOp(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '700', color });
}

function badgeRect(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string, w = 120, h = 32): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): SchedulerStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function subRowLabel(g: Gsel, cx: number, rowY: number, text: string): void {
  lbl(g, cx, rowY - MAT_H / 2 - 20, text, { size: 9, color: COLORS.update.stroke, weight: '600' });
}

function dArrow(g: Gsel, x1: number, y1: number, x2: number, y2: number, color: string): void {
  drawArrow(g as Sel, x1, y1, x2, y2, { color });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Per-scheduler update-step renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderDdpmUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  let rowY = y + BOX_TO_ROW;
  const shape = `[${nPatches}, ${dModel}]`;

  // ── Sub-step 1: scale predicted noise ────────────────────────────────────
  subRowLabel(g, cx, rowY, '1) scale predicted noise');
  seqMatrix(g, 90, rowY, 'ε_θ', shape, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  smallOp(g, 180, rowY, '×', COLORS.update.stroke);
  smallVec(g, 270, rowY, 'β_t/√(1-ᾱ_t)', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 120, VEC_H);
  seqMatrix(g, 410, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 180 - 14, rowY, { color: COLORS.model.stroke });
  drawArrow(g as Sel, 270 + 60 + 4, rowY, 180 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 180 + 14, rowY, 410 - 70 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `s = β_t/√(1-ᾱ_t) · ε_θ  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 2: posterior mean ───────────────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '2) posterior mean');
  seqMatrix(g, 90, rowY, 'z_t', shape, COLORS.latent.fill, COLORS.latent.stroke, 140, MAT_H);
  smallOp(g, 200, rowY, '-', COLORS.update.stroke);
  seqMatrix(g, 330, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  smallOp(g, 460, rowY, '/', COLORS.update.stroke);
  smallVec(g, 550, rowY, '√α_t', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  seqMatrix(g, 690, rowY, 'μ_θ', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 200 - 14, rowY, { color: COLORS.latent.stroke });
  drawArrow(g as Sel, 330 + 70 + 4, rowY, 200 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 200 + 14, rowY, 460 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 550 - 40 - 4, rowY, 460 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 460 + 14, rowY, 690 - 70 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 410, rowY - ROW_GAP + MAT_H / 2 + 4, 330, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `μ_θ = (z_t − s) / √α_t  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 3: add stochastic noise ─────────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '3) add stochastic noise');
  seqMatrix(g, 180, rowY, 'μ_θ', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  smallOp(g, 310, rowY, '+', COLORS.update.stroke);
  smallVec(g, 440, rowY, '√β_t·ε', '[D]', COLORS.noise.fill, COLORS.noise.stroke, 110, VEC_H);
  lbl(g, 440, rowY - 28, 'ε ~ N(0,I)', { size: 8, color: COLORS.noise.stroke, weight: '600' });
  seqMatrix(g, 600, rowY, 'z_{t-1}', shape, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);

  drawArrow(g as Sel, 180 + 70 + 4, rowY, 310 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 440 - 55 - 4, rowY, 310 + 14, rowY, { color: COLORS.noise.stroke });
  drawArrow(g as Sel, 310 + 14, rowY, 600 - 75 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 690, rowY - ROW_GAP + MAT_H / 2 + 4, 180 + 70, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = μ_θ + √β_t · ε  →  ${shape}`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderDdimUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  let rowY = y + BOX_TO_ROW;
  const shape = `[${nPatches}, ${dModel}]`;

  // ── Sub-step 1: scale predicted noise ────────────────────────────────────
  subRowLabel(g, cx, rowY, '1) scale predicted noise');
  seqMatrix(g, 90, rowY, 'ε_θ', shape, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  smallOp(g, 180, rowY, '×', COLORS.update.stroke);
  smallVec(g, 270, rowY, '√(1-ᾱ_t)', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 120, VEC_H);
  seqMatrix(g, 410, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 180 - 14, rowY, { color: COLORS.model.stroke });
  drawArrow(g as Sel, 270 + 60 + 4, rowY, 180 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 180 + 14, rowY, 410 - 70 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `s = √(1-ᾱ_t) · ε_θ  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 2: predict clean latent x_0_pred ────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '2) predict clean latent x_0_pred');
  seqMatrix(g, 90, rowY, 'z_t', shape, COLORS.latent.fill, COLORS.latent.stroke, 140, MAT_H);
  smallOp(g, 200, rowY, '-', COLORS.update.stroke);
  seqMatrix(g, 330, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  smallOp(g, 460, rowY, '/', COLORS.update.stroke);
  smallVec(g, 550, rowY, '√ᾱ_t', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  seqMatrix(g, 690, rowY, 'x_0_pred', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 200 - 14, rowY, { color: COLORS.latent.stroke });
  drawArrow(g as Sel, 330 + 70 + 4, rowY, 200 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 200 + 14, rowY, 460 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 550 - 40 - 4, rowY, 460 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 460 + 14, rowY, 690 - 70 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 410, rowY - ROW_GAP + MAT_H / 2 + 4, 330, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `x_0_pred = (z_t − s) / √ᾱ_t  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 3: reconstruct z_{t-1} from two branches ────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '3) reconstruct z_{t-1}');
  // branch A
  seqMatrix(g, 90, rowY, 'x_0_pred', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  smallOp(g, 200, rowY, '×', COLORS.update.stroke);
  smallVec(g, 290, rowY, '√ᾱ_{t-1}', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 120, VEC_H);
  seqMatrix(g, 430, rowY, 'term_1', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);
  // branch B
  seqMatrix(g, 580, rowY, 'ε_θ', shape, COLORS.model.fill, COLORS.model.stroke, 130, MAT_H);
  smallOp(g, 680, rowY, '×', COLORS.update.stroke);
  smallVec(g, 780, rowY, '√(1-ᾱ_{t-1})', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 130, VEC_H);
  seqMatrix(g, 930, rowY, 'term_2', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 200 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 290 + 60 + 4, rowY, 200 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 200 + 14, rowY, 430 - 65 - 4, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 580 + 65 + 4, rowY, 680 - 14, rowY, { color: COLORS.model.stroke });
  drawArrow(g as Sel, 780 + 65 + 4, rowY, 680 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 680 + 14, rowY, 930 - 65 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 690, rowY - ROW_GAP + MAT_H / 2 + 4, 90 + 70, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `term_1 = √ᾱ_{t-1}·x_0_pred    term_2 = √(1-ᾱ_{t-1})·ε_θ`, COLORS.update.stroke);

  // ── Sub-step 4: add the two terms ────────────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '4) combine terms');
  seqMatrix(g, 310, rowY, 'term_1', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);
  smallOp(g, 430, rowY, '+', COLORS.update.stroke);
  seqMatrix(g, 550, rowY, 'term_2', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);
  seqMatrix(g, 730, rowY, 'z_{t-1}', shape, COLORS.out.fill, COLORS.out.stroke, 140, MAT_H);

  drawArrow(g as Sel, 310 + 65 + 4, rowY, 430 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 550 - 65 - 4, rowY, 430 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 430 + 14, rowY, 730 - 70 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 430, rowY - ROW_GAP + MAT_H / 2 + 4, 310 + 65, rowY - MAT_H / 2 - 4, COLORS.update.stroke);
  dArrow(g, 930, rowY - ROW_GAP + MAT_H / 2 + 4, 550 + 65, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = term_1 + term_2  →  ${shape}`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderEulerUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  let rowY = y + BOX_TO_ROW;
  const shape = `[${nPatches}, ${dModel}]`;

  // ── Sub-step 1: scale predicted noise by schedule sigma ──────────────────
  subRowLabel(g, cx, rowY, '1) scale predicted noise');
  seqMatrix(g, 90, rowY, 'ε_θ', shape, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  smallOp(g, 200, rowY, '×', COLORS.update.stroke);
  smallVec(g, 290, rowY, 'σ_t', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  seqMatrix(g, 430, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 200 - 14, rowY, { color: COLORS.model.stroke });
  drawArrow(g as Sel, 290 - 40 - 4, rowY, 200 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 200 + 14, rowY, 430 - 70 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `s = σ_t · ε_θ  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 2: residual update ──────────────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '2) residual update');
  seqMatrix(g, 90, rowY, 'z_t', shape, COLORS.latent.fill, COLORS.latent.stroke, 140, MAT_H);
  smallOp(g, 230, rowY, '-', COLORS.update.stroke);
  seqMatrix(g, 380, rowY, 's', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  seqMatrix(g, 590, rowY, 'z_{t-1}', shape, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);

  drawArrow(g as Sel, 90 + 70 + 4, rowY, 230 - 14, rowY, { color: COLORS.latent.stroke });
  drawArrow(g as Sel, 380 + 70 + 4, rowY, 230 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 230 + 14, rowY, 590 - 75 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 430, rowY - ROW_GAP + MAT_H / 2 + 4, 380 + 70, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = z_t − s  →  ${shape}`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderDpmppUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  let rowY = y + BOX_TO_ROW;
  const shape = `[${nPatches}, ${dModel}]`;

  // ── Sub-step 1: scale current noise estimate ─────────────────────────────
  subRowLabel(g, cx, rowY, '1) scale current noise ε_t');
  seqMatrix(g, 90, rowY, 'ε_t', shape, COLORS.model.fill, COLORS.model.stroke, 130, MAT_H);
  smallOp(g, 180, rowY, '×', COLORS.update.stroke);
  smallVec(g, 270, rowY, 'γ_1', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  seqMatrix(g, 400, rowY, 'term_1', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);

  drawArrow(g as Sel, 90 + 65 + 4, rowY, 180 - 14, rowY, { color: COLORS.model.stroke });
  drawArrow(g as Sel, 270 - 40 - 4, rowY, 180 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 180 + 14, rowY, 400 - 65 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `term_1 = γ_1 · ε_t  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 2: add to z_t ───────────────────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '2) accumulate first term');
  seqMatrix(g, 90, rowY, 'z_t', shape, COLORS.latent.fill, COLORS.latent.stroke, 130, MAT_H);
  smallOp(g, 220, rowY, '+', COLORS.update.stroke);
  seqMatrix(g, 360, rowY, 'term_1', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);
  seqMatrix(g, 540, rowY, 'partial', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);

  drawArrow(g as Sel, 90 + 65 + 4, rowY, 220 - 14, rowY, { color: COLORS.latent.stroke });
  drawArrow(g as Sel, 360 + 65 + 4, rowY, 220 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 220 + 14, rowY, 540 - 70 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 400, rowY - ROW_GAP + MAT_H / 2 + 4, 360 + 65, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `partial = z_t + term_1  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 3: scale previous noise estimate ────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '3) scale previous noise ε_{t-1}');
  seqMatrix(g, 90, rowY, 'ε_{t-1}', shape, COLORS.noise.fill, COLORS.noise.stroke, 130, MAT_H);
  smallOp(g, 180, rowY, '×', COLORS.update.stroke);
  smallVec(g, 270, rowY, 'γ_2', '[D]', COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  seqMatrix(g, 400, rowY, 'term_2', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);

  drawArrow(g as Sel, 90 + 65 + 4, rowY, 180 - 14, rowY, { color: COLORS.noise.stroke });
  drawArrow(g as Sel, 270 - 40 - 4, rowY, 180 + 14, rowY, { color: COLORS.schedule.stroke });
  drawArrow(g as Sel, 180 + 14, rowY, 400 - 65 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `term_2 = γ_2 · ε_{t-1}  →  ${shape}`, COLORS.update.stroke);

  // ── Sub-step 4: final multi-step update ──────────────────────────────────
  rowY += MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  subRowLabel(g, cx, rowY, '4) final update');
  seqMatrix(g, 170, rowY, 'partial', shape, COLORS.update.fill, COLORS.update.stroke, 140, MAT_H);
  smallOp(g, 340, rowY, '+', COLORS.update.stroke);
  seqMatrix(g, 480, rowY, 'term_2', shape, COLORS.update.fill, COLORS.update.stroke, 130, MAT_H);
  seqMatrix(g, 700, rowY, 'z_{t-1}', shape, COLORS.out.fill, COLORS.out.stroke, 140, MAT_H);

  drawArrow(g as Sel, 170 + 70 + 4, rowY, 340 - 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 480 - 65 - 4, rowY, 340 + 14, rowY, { color: COLORS.update.stroke });
  drawArrow(g as Sel, 340 + 14, rowY, 700 - 70 - 4, rowY, { color: COLORS.update.stroke });
  dArrow(g, 540, rowY - ROW_GAP * 2 + MAT_H / 2 + 4, 170 + 70, rowY - MAT_H / 2 - 4, COLORS.update.stroke);
  dArrow(g, 400, rowY - ROW_GAP + MAT_H / 2 + 4, 480 + 65, rowY - MAT_H / 2 - 4, COLORS.update.stroke);

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = partial + term_2  →  ${shape}`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDiffusionSchedulerDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const nPatches = Number(params.n_patches) || 256;
  const dModel = Number(params.d_model) || 768;
  const steps = Number(params.steps) || 50;
  const scheduler = String(params.scheduler || 'ddpm') as SchedulerType;

  const schedulerLabel: Record<SchedulerType, string> = {
    ddpm: 'DDPM (stochastic)',
    ddim: 'DDIM (deterministic)',
    euler: 'Euler (flow-based)',
    'dpm++': 'DPM++ 2M (multi-step)',
  };

  const stepsMeta: SchedulerStep[] = [];
  let stepId = 0;
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Diffusion Scheduler', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8, `${schedulerLabel[scheduler]} — iteratively denoise latents using a noise schedule`, { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `patches: ${nPatches}`, `d_model: ${dModel}`, `steps: ${steps}`, `scheduler: ${scheduler.toUpperCase()}`,
  ]);
  y += 32;

  // ── Step 1: Input ────────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Noisy Latent & Timestep',
      `z_t: [${nPatches}, ${dModel}]    t: [1]`,
      COLORS.latent.fill, COLORS.latent.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 170, MAT_H);
    lbl(gs, CX - 200, rowY - MAT_H / 2 - 14, 'Noisy Latent', { size: 10, color: COLORS.latent.stroke, weight: '600' });

    const tW = 110;
    drawMatrixBlock(gs as Sel, CX + 200 - tW / 2, rowY - 18, {
      width: tW, height: 36, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });
    lbl(gs, CX + 200, rowY - 32, 'Timestep', { size: 10, color: COLORS.time.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 22,
      `z_t is the noisy latent at timestep t (t=${steps} ... 0)`, COLORS.latent.stroke);

    stepsMeta.push(makeStep(stepId, 'Input', 'Input: Noisy Latent & Timestep',
      `z_t [${nPatches}, ${dModel}], t [1]`,
      'The diffusion sampling loop starts from a noisy latent z_t and a scalar timestep t.',
      'step-input', COLORS.latent.stroke, COLORS.latent.fill,
      [`z_t = noisy latent at timestep t   # [${nPatches}, ${dModel}]`,
       `t   = current timestep scalar        # e.g. ${steps} -> 0`]));
    y = rowY + MAT_H / 2 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 2: Predict Noise ────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-predict', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Predict Noise',
      `ε_θ = DiT(z_t, t)  →  [${nPatches}, ${dModel}]`,
      COLORS.model.fill, COLORS.model.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const zCx = CX - 240;
    const ditCx = CX + 40;
    const epsCx = CX + 220;

    seqMatrix(gs, zCx, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 160, MAT_H);

    const tW = 80;
    drawMatrixBlock(gs as Sel, ditCx - tW / 2, rowY - 50, {
      width: tW, height: 32, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });

    badgeRect(gs, ditCx, rowY, 'DiT', COLORS.model.fill, COLORS.model.stroke, 90, 36);
    seqMatrix(gs, epsCx, rowY, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 170, MAT_H);
    lbl(gs, epsCx, rowY - MAT_H / 2 - 14, 'Predicted Noise', { size: 10, color: COLORS.model.stroke, weight: '600' });

    drawArrow(g as Sel, zCx + 80 + 4, rowY, ditCx - 45 - 4, rowY, { color: COLORS.latent.stroke });
    drawArrow(g as Sel, ditCx, rowY - 34, ditCx, rowY - 18, { color: COLORS.time.stroke });
    drawArrow(g as Sel, ditCx + 45 + 4, rowY, epsCx - 85 - 4, rowY, { color: COLORS.model.stroke });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `ε_θ = DiT(z_t, t)  →  [${nPatches}, ${dModel}]`, COLORS.model.stroke);

    stepsMeta.push(makeStep(stepId, 'Predict', 'Predict Noise',
      `ε_θ = DiT(z_t, t)`,
      'The diffusion model predicts the noise that was added to the clean latent.',
      'step-predict', COLORS.model.stroke, COLORS.model.fill,
      [`# Noise prediction network (e.g. DiT)`,
       `eps_pred = model(z_t, t)   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 3: Schedule Coefficients ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-schedule', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Schedule Coefficients',
      `lookup α_t, ᾱ_t, β_t, σ_t from ${scheduler.toUpperCase()} schedule`,
      COLORS.schedule.fill, COLORS.schedule.stroke);

    arrowDown(gs, CX + 160, y, hBottom, COLORS.time.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const tCx = CX - 280;
    const schedCx = CX - 80;
    const coeffCx = CX + 150;

    const tW = 80;
    drawMatrixBlock(gs as Sel, tCx - tW / 2, rowY - 16, {
      width: tW, height: 32, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });

    badgeRect(gs, schedCx, rowY, 'Schedule', COLORS.schedule.fill, COLORS.schedule.stroke, 130, 36);
    lbl(gs, schedCx, rowY - 28, 'lookup coefficients', { size: 9, color: COLORS.schedule.stroke, weight: '600' });

    const coeffW = 320;
    const coeffH = 44;
    drawMatrixBlock(gs as Sel, coeffCx - coeffW / 2, rowY - coeffH / 2, {
      width: coeffW, height: coeffH, label: 'coeffs', sublabel: `[α_t, ᾱ_t, β_t, σ_t]`,
      fill: COLORS.schedule.fill, stroke: COLORS.schedule.stroke, cols: 4, rows: 1,
    });

    drawArrow(g as Sel, tCx + tW / 2 + 4, rowY, schedCx - 65 - 4, rowY, { color: COLORS.time.stroke });
    drawArrow(g as Sel, schedCx + 65 + 4, rowY, coeffCx - coeffW / 2 - 4, rowY, { color: COLORS.schedule.stroke });

    const sigmaNote = scheduler === 'ddpm' ? 'σ_t = √β_t' :
                      scheduler === 'ddim' ? 'σ_t unused (deterministic)' :
                      scheduler === 'euler' ? 'σ_t = flow step size' :
                      'σ_t unused; γ_i from DPM++ coefficients';
    shapeEq(gs, CX, rowY + coeffH / 2 + 24,
      `β_t = 1 − α_t ;  ᾱ_t = ∏_{i=1}^{t} α_i ;  ${sigmaNote}`, COLORS.schedule.stroke);

    stepsMeta.push(makeStep(stepId, 'Schedule', 'Schedule Coefficients',
      `lookup α_t, ᾱ_t, β_t, σ_t`,
      'The scheduler maps timestep t to coefficients that control how much noise is removed and how much randomness is injected.',
      'step-schedule', COLORS.schedule.stroke, COLORS.schedule.fill,
      [`# Coefficient lookup from precomputed schedule`,
       `alpha_t, alpha_bar_t, beta_t, sigma_t = schedule[t]`]));
    y = rowY + coeffH / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 4: Update Rule (per scheduler) ──────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-update', stepId);
    const title = scheduler === 'ddpm' ? 'DDPM Update (Stochastic)' :
                  scheduler === 'ddim' ? 'DDIM Update (Deterministic)' :
                  scheduler === 'euler' ? 'Euler Update (Flow-based)' :
                  'DPM++ 2M Update (Multi-step)';
    const formula = scheduler === 'ddpm' ? `z_{t-1} = μ_θ + √β_t·ε ;  μ_θ = (z_t − s)/√α_t,  s = β_t/√(1−ᾱ_t)·ε_θ` :
                    scheduler === 'ddim' ? `z_{t-1} = √ᾱ_{t-1}·x_0_pred + √(1−ᾱ_{t-1})·ε_θ` :
                    scheduler === 'euler' ? `z_{t-1} = z_t − σ_t·ε_θ` :
                    `z_{t-1} = z_t + γ_1·ε_t + γ_2·ε_{t-1}`;
    const hBottom = stepHeader(gs, CX, y, stepId, title, formula, COLORS.update.fill, COLORS.update.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.model.stroke);

    let nextY: number;
    switch (scheduler) {
      case 'ddim': nextY = renderDdimUpdate(gs, CX, hBottom, nPatches, dModel); break;
      case 'euler': nextY = renderEulerUpdate(gs, CX, hBottom, nPatches, dModel); break;
      case 'dpm++': nextY = renderDpmppUpdate(gs, CX, hBottom, nPatches, dModel); break;
      default: nextY = renderDdpmUpdate(gs, CX, hBottom, nPatches, dModel); break;
    }

    const explanation = scheduler === 'ddpm'
      ? 'DDPM first scales the predicted noise, then computes the posterior mean μ_θ, and finally samples z_{t-1} by adding Gaussian noise.'
      : scheduler === 'ddim'
      ? 'DDIM is deterministic: it predicts the clean latent x_0_pred and reconstructs z_{t-1} from a weighted combination of x_0_pred and the predicted noise.'
      : scheduler === 'euler'
      ? 'Euler scales the predicted noise by the schedule sigma and subtracts it from z_t in a single residual step.'
      : 'DPM++ is a higher-order solver: it scales the current and previous noise estimates and accumulates them onto z_t in two stages.';

    const codeLines = scheduler === 'ddpm'
      ? [`s = beta_t / sqrt(1 - alpha_bar_t) * eps_pred`,
         `mu = (z_t - s) / sqrt(alpha_t)`,
         `z_tminus1 = mu + sqrt(beta_t) * randn_like(z_t)`]
      : scheduler === 'ddim'
      ? [`s = sqrt(1 - alpha_bar_t) * eps_pred`,
         `x0_pred = (z_t - s) / sqrt(alpha_bar_t)`,
         `term_1 = sqrt(alpha_bar_t_1) * x0_pred`,
         `term_2 = sqrt(1 - alpha_bar_t_1) * eps_pred`,
         `z_tminus1 = term_1 + term_2`]
      : scheduler === 'euler'
      ? [`s = sigma_t * eps_pred`,
         `z_tminus1 = z_t - s`]
      : [`term_1 = gamma_1 * eps_t`,
         `partial = z_t + term_1`,
         `term_2 = gamma_2 * eps_t_1`,
         `z_tminus1 = partial + term_2`];

    stepsMeta.push(makeStep(stepId, 'Update', title, formula, explanation, 'step-update',
      COLORS.update.stroke, COLORS.update.fill, codeLines));
    y = nextY + STEP_GAP;
  }

  // ── Step 5: Iteration Loop ───────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-loop', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Iteration Loop',
      `repeat steps 2-4 for t = ${steps}, ${Math.max(1, steps - 1)}, ..., 0`,
      COLORS.schedule.fill, COLORS.schedule.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.update.stroke);

    const rowY = hBottom + BOX_TO_ROW;

    // Loop body visual: z_t -> [predict -> schedule -> update] -> z_{t-1}
    seqMatrix(gs, CX - 360, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 140, MAT_H);
    badgeRect(gs, CX - 220, rowY, 'predict', COLORS.model.fill, COLORS.model.stroke, 100, 34);
    drawArrow(g as Sel, CX - 360 + 70 + 4, rowY, CX - 220 - 50 - 4, rowY, { color: COLORS.latent.stroke });

    badgeRect(gs, CX - 80, rowY, 'schedule', COLORS.schedule.fill, COLORS.schedule.stroke, 110, 34);
    drawArrow(g as Sel, CX - 220 + 50 + 4, rowY, CX - 80 - 55 - 4, rowY, { color: COLORS.model.stroke });

    badgeRect(gs, CX + 60, rowY, 'update', COLORS.update.fill, COLORS.update.stroke, 90, 34);
    drawArrow(g as Sel, CX - 80 + 55 + 4, rowY, CX + 60 - 45 - 4, rowY, { color: COLORS.schedule.stroke });

    seqMatrix(gs, CX + 230, rowY, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);
    drawArrow(g as Sel, CX + 60 + 45 + 4, rowY, CX + 230 - 75 - 4, rowY, { color: COLORS.update.stroke });

    // Feedback arrow (curves below the loop row, from z_{t-1} back to z_t)
    const feedbackD = `M ${CX + 230} ${rowY + MAT_H / 2 + 4} C ${CX + 230} ${rowY + 170}, ${CX - 360} ${rowY + 170}, ${CX - 360} ${rowY + MAT_H / 2 + 4}`;
    gs.append('path')
      .attr('d', feedbackD)
      .attr('fill', 'none')
      .attr('stroke', COLORS.update.stroke)
      .attr('stroke-width', 1.5)
      .attr('stroke-dasharray', '6,4')
      .attr('marker-end', 'url(#arrowhead-loop)');

    // Marker for loop arrow
    g.append('defs').append('marker')
      .attr('id', 'arrowhead-loop')
      .attr('viewBox', '0 -5 10 10')
      .attr('refX', 8)
      .attr('refY', 0)
      .attr('markerWidth', 6)
      .attr('markerHeight', 6)
      .attr('orient', 'auto')
      .append('path')
      .attr('d', 'M0,-5L10,0L0,5')
      .attr('fill', COLORS.update.stroke);

    lbl(gs, CX - 65, rowY + MAT_H / 2 + 86, `repeat ${steps} times   (t → t-1)`, {
      size: 10, color: COLORS.update.stroke, weight: '600', anchor: 'middle'
    });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 150,
      `sampling loop: z_T (pure noise) → z_0 (clean latent) in ${steps} steps`, COLORS.schedule.stroke);

    stepsMeta.push(makeStep(stepId, 'Loop', 'Iteration Loop',
      `for t = ${steps} ... 0: z_{t-1} = update(z_t, ε_θ, schedule[t])`,
      'The update is repeated for every timestep, gradually converting random noise into a clean latent image.',
      'step-loop', COLORS.schedule.stroke, COLORS.schedule.fill,
      [`for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)`,
       `    z_t = scheduler_step(z_t, eps, t)`]));
    y = rowY + MAT_H / 2 + 150 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 6: Output ───────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output: Denoised Latent',
      `z_0: [${nPatches}, ${dModel}]`,
      COLORS.out.fill, COLORS.out.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.update.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX, rowY, 'z_0', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 260, MAT_H);
    lbl(gs, CX, rowY - MAT_H / 2 - 16, 'Final Denoised Latent', { size: 12, color: COLORS.out.stroke, weight: '700' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
      `z_0 [${nPatches}, ${dModel}] — sent to VAE decoder to produce the output image`, COLORS.out.stroke);

    stepsMeta.push(makeStep(stepId, 'Output', 'Output: Denoised Latent',
      `z_0 [${nPatches}, ${dModel}]`,
      'After the final timestep, the latent z_0 is decoded by the VAE to produce the generated image.',
      'step-output', COLORS.out.stroke, COLORS.out.fill,
      [`# Final denoised latent`,
       `image = vae_decoder(z_0)   # [3, H, W]`]));
    y = rowY + MAT_H / 2 + 28 + SHAPE_GAP;
  }

  // ── Footer ───────────────────────────────────────────────────────────────
  y += 32;
  const insightText = scheduler === 'ddpm'
    ? 'DDPM is the original stochastic sampler. It scales the predicted noise, computes the posterior mean, and adds random noise at each step, so the same prompt yields different images. More steps reduce artifacts but increase cost.'
    : scheduler === 'ddim'
    ? 'DDIM removes the per-step random noise, making sampling deterministic. It can also use fewer steps (e.g. 20-50) with little quality loss, which is why it is popular for fast inference.'
    : scheduler === 'euler'
    ? 'Euler is a simple first-order ODE solver. It is fast and works well for flow-matching models, but may need careful step-size tuning for high-quality results.'
    : 'DPM++ uses a second-order update rule with past noise estimates. It often gives higher-quality samples in 10-30 steps, trading slightly more memory for fewer function evaluations.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Each sampling step requires one forward pass of the denoising model. Total cost scales as O(steps × patches × d_model²). Fewer steps or faster schedulers (DDIM/Euler) reduce latency.`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'dit-architecture', 'DiT Architecture');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'image-tokenizer', 'Image Tokenizer');
  y += 72;

  const codeTitle = `Diffusion Scheduler — ${scheduler.toUpperCase()} (PyTorch)`;
  const codeLines = scheduler === 'ddpm'
    ? [`# DDPM sampling`,
       `for t in reversed(range(${steps})):`,
       `    eps_pred = model(z_t, t)                  # [${nPatches}, ${dModel}]`,
       `    alpha_t = schedule.alpha[t]`,
       `    alpha_bar_t = schedule.alpha_bar[t]`,
       `    beta_t = 1 - alpha_t`,
       `    s = beta_t / sqrt(1 - alpha_bar_t) * eps_pred`,
       `    mu = (z_t - s) / sqrt(alpha_t)`,
       `    z_t = mu + sqrt(beta_t) * torch.randn_like(z_t)`]
    : scheduler === 'ddim'
    ? [`# DDIM sampling`,
       `for t in reversed(range(${steps})):`,
       `    eps_pred = model(z_t, t)`,
       `    alpha_bar_t = schedule.alpha_bar[t]`,
       `    alpha_bar_t_1 = schedule.alpha_bar[t-1] if t > 0 else 1.0`,
       `    s = sqrt(1 - alpha_bar_t) * eps_pred`,
       `    x0_pred = (z_t - s) / sqrt(alpha_bar_t)`,
       `    term_1 = sqrt(alpha_bar_t_1) * x0_pred`,
       `    term_2 = sqrt(1 - alpha_bar_t_1) * eps_pred`,
       `    z_t = term_1 + term_2`]
    : scheduler === 'euler'
    ? [`# Euler sampler`,
       `for t in reversed(range(${steps})):`,
       `    eps_pred = model(z_t, t)`,
       `    sigma_t = schedule.sigma[t]`,
       `    s = sigma_t * eps_pred`,
       `    z_t = z_t - s`]
    : [`# DPM++ 2M sampler`,
       `eps_prev = None`,
       `for t in reversed(range(${steps})):`,
       `    eps_t = model(z_t, t)`,
       `    if eps_prev is not None:`,
       `        term_1 = gamma_1 * eps_t`,
       `        partial = z_t + term_1`,
       `        term_2 = gamma_2 * eps_prev`,
       `        z_t = partial + term_2`,
       `    eps_prev = eps_t`];

  drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160, codeTitle,
    [`${schedulerLabel[scheduler]} — ${nPatches} patches, d=${dModel}, ${steps} steps`], codeLines);

  return { width: W, height: y + 160, steps: stepsMeta };
}
